    rate = tax_rates.get(state, 0.0)
    return round(amount * rate, 2)

def merge_intervals(iv: list) -> list:
    if not iv:
        return []

    # Sort intervals based on start time
    iv.sort()

    merged = [iv[0]]

    for current in iv[1:]:
        last = merged[-1]
        if current[0] <= last[1]:
            # Overlapping intervals, update the end of the last merged interval
            merged[-1][1] = max(last[1], current[1])
        else:
            # Non-overlapping, add the current interval
            merged.append(current)

    return merged

def valid_parens(s: str) -> bool:
    stack = []
    mapping = {')': '(', '}': '{', ']': '['}
    for char in s:
        if char in mapping:
            if not stack or stack.pop() != mapping[char]:
                return False
        else:
            stack.append(char)
    return not stack
